'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>'MK '+Number(n||0).toLocaleString('en-MW',{minimumFractionDigits:2,maximumFractionDigits:2}),today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Blantyre',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),types=['Church','Mphakati','Banki mkhonde','Trip','Cause / fundraiser','Funeral / welfare','School / community','Investment savings','Member lending','Emergency welfare fund','School-fee support','Community project','Bulk purchasing','Event / trip fund','Other'];
let config={},session=null,groups=[],openId=null,view='people',loading=false,publicData=null,lastSync='',refreshPromise=null;
const publicId=new URLSearchParams(location.search).get('collection');
const publicToken=new URLSearchParams(location.search).get('token');
try{session=JSON.parse(sessionStorage.getItem('sungira.session')||'null')}catch{}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500)}
function setSession(s){session=s;if(s)sessionStorage.setItem('sungira.session',JSON.stringify(s));else sessionStorage.removeItem('sungira.session')}
async function auth(path,data,method='POST',token){const r=await fetch(config.url+'/auth/v1/'+path,{method,headers:{apikey:config.key,'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},...(method==='GET'?{}:{body:JSON.stringify(data)})});const out=await r.json();if(!r.ok)throw Error(out.msg||out.error_description||out.message||'Please check your details and try again.');return out}
async function accessToken(){if(!session)return null;const expires=(session.expires_at||0)*1000;if(expires&&expires<Date.now()+60000){if(!refreshPromise)refreshPromise=auth('token?grant_type=refresh_token',{refresh_token:session.refresh_token}).then(s=>{s.expires_at=Math.floor(Date.now()/1000)+s.expires_in;setSession(s);return s.access_token}).finally(()=>refreshPromise=null);return refreshPromise}return session.access_token}
async function api(action,data={}){const token=action==='public'?null:await accessToken();const r=await fetch('/.netlify/functions/api',{method:'POST',headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:JSON.stringify({action,data})});const out=await r.json();if(!r.ok){if(r.status===401){setSession(null);groups=[];openId=null;render()}const error=Error(out.error||'Something went wrong. Please try again.');error.status=r.status;throw error}return out}
function field(name,label,type='text',value='',attrs=''){return `<label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}>`}
function choice(name,label,values,value){return `<label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${values.map(v=>`<option ${value===v?'selected':''}>${esc(v)}</option>`).join('')}</select>`}
function check(name,label,value=false){return `<label class="check"><input name="${name}" type="checkbox" ${value?'checked':''}> ${label}</label>`}
function modal(title,fields,handler,saveLabel='Save'){if($('#dialog').open)$('#dialog').close();$('#dialog').innerHTML=`<form><h2>${title}</h2>${fields}<p id="formError" class="negative" role="alert"></p><div class="actions"><button class="primary" type="submit">${saveLabel}</button><button id="cancel" type="button">Cancel</button></div></form>`;$('#cancel').onclick=()=>$('#dialog').close();$('#dialog form').onsubmit=async e=>{e.preventDefault();const form=e.target,button=form.querySelector('[type=submit]'),d=Object.fromEntries(new FormData(form));button.disabled=true;$('#formError').textContent='';try{await handler(d,form);$('#dialog').close();await sync();render()}catch(err){$('#formError').textContent=err.message}finally{button.disabled=false}};$('#dialog').showModal();$('#dialog input')?.focus()}
function selected(){return groups.find(g=>g.id===openId)}
function canManage(g=selected()){return ['Owner','Treasurer'].includes(g?.role)}
function sum(a){return a.reduce((s,e)=>s+Number(e.amount),0)}
function totals(d){const confirmed=d.ledger.filter(e=>e.status==='Confirmed'),incoming=['Contribution','Loan repayment','Investment proceeds'],outgoing=['Expense','Mkhonde payout','Investment placement','Loan disbursement'];const collected=sum(confirmed.filter(e=>e.kind==='Contribution')),spent=sum(confirmed.filter(e=>['Expense','Mkhonde payout'].includes(e.kind))),balance=sum(confirmed.filter(e=>incoming.includes(e.kind)))-sum(confirmed.filter(e=>outgoing.includes(e.kind))),investmentBook=sum(confirmed.filter(e=>e.kind==='Investment placement'))-confirmed.filter(e=>e.kind==='Investment proceeds').reduce((s,e)=>s+Number(e.basisReleased||0),0),loanPrincipal=sum(confirmed.filter(e=>e.kind==='Loan disbursement'))-confirmed.reduce((s,e)=>s+Number(e.principalPaid||0)+Number(e.principalWrittenOff||0),0),interestReceived=confirmed.reduce((s,e)=>s+Number(e.interestPaid||0),0),investmentGain=confirmed.filter(e=>e.kind==='Investment proceeds').reduce((s,e)=>s+Number(e.amount)-Number(e.basisReleased||0),0);return{collected,spent,balance,pending:sum(d.ledger.filter(e=>e.status==='Pending')),target:Number(d.target)||d.members.reduce((s,m)=>s+Number(m.pledge),0),investmentBook,loanPrincipal,assets:balance+investmentBook+loanPrincipal,interestReceived,investmentGain,loanWriteoffs:confirmed.reduce((s,e)=>s+Number(e.principalWrittenOff||0),0)}}

function paid(d,m){return sum(d.ledger.filter(e=>e.status==='Confirmed'&&e.kind==='Contribution'&&e.member===m.id))}
function stat(label,n){return `<div class="stat"><span>${label}</span><strong>${money(n)}</strong></div>`}
function download(name,body,type='application/json'){const u=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
async function sync(quiet=false){if(loading||$('#dialog').open&&quiet)return;loading=true;try{if(publicId){const next=await api('public',{id:publicId,token:publicToken});const changed=JSON.stringify(next)!==JSON.stringify(publicData);publicData=next;if(quiet&&changed)renderPublic()}else if(session){const next=await api('list');const changed=JSON.stringify(next)!==JSON.stringify(groups);groups=next;if(!quiet)config.seedAllowed=(await api('seed_status')).allowed;if(quiet&&changed)render()}lastSync=new Date().toLocaleTimeString();$('#connection').textContent='Connected · Updated '+lastSync+' · Changes refresh every 10 seconds';}catch(e){$('#connection').textContent='Connection paused · '+e.message;if(publicId&&e.status===400){publicData=null;renderPublic()}if(!quiet)throw e}finally{loading=false}}
function account(){const root=$('#account');if(publicId){root.innerHTML='<a class="button" href="./">Officer sign in</a><button id="help">Help</button>';$('#help').onclick=help;return}root.innerHTML=session?`<span>${esc(session.user?.email||'Signed in')}</span><button id="logout">Sign out</button><button id="help">Help</button>`:`<button id="login">Officer sign in</button><button class="primary" id="signup">Create officer account</button><button id="help">Help</button>`;$('#login')?.addEventListener('click',()=>accountForm());$('#signup')?.addEventListener('click',()=>accountForm(true));$('#logout')?.addEventListener('click',async()=>{try{const token=await accessToken();await auth('logout',{},'POST',token)}catch{}setSession(null);groups=[];openId=null;location.href=location.pathname});$('#help').onclick=help}
function accountForm(signup=false){if(!config.ready){toast('Shared accounts need the one-time setup first.');return}modal(signup?'Create an officer account':'Officer sign in',`${signup?field('name','Your name','text','','required autocomplete="name"'):''}${field('email','Email address','email','','required autocomplete="email"')}${field('password','Password','password','','required minlength="8" autocomplete="'+(signup?'new-password':'current-password')+'"')}<p class="muted">${signup?'Use at least 8 characters. We will email a confirmation link.':'Your group appears after you sign in with the email the organiser added.'}</p>${!signup?'<button type="button" id="forgot">Forgot password?</button>':''}`,async d=>{if(signup){const out=await auth('signup?redirect_to='+encodeURIComponent(location.origin+location.pathname),{email:d.email,password:d.password,data:{name:d.name}});if(out.access_token){out.expires_at=Math.floor(Date.now()/1000)+out.expires_in;setSession(out)}else toast('Check your email and confirm your account, then sign in.')}else{const out=await auth('token?grant_type=password',{email:d.email,password:d.password});out.expires_at=Math.floor(Date.now()/1000)+out.expires_in;setSession(out)}},signup?'Create account':'Sign in');$('#forgot')?.addEventListener('click',()=>modal('Reset your password',field('email','Email address','email','','required'),async d=>{await auth('recover?redirect_to='+encodeURIComponent(location.origin+location.pathname),{email:d.email});toast('If the account exists, a password reset email has been sent.')},'Send reset email'))}
function help(){modal('How Sungira works',`<ol><li><strong>Members open their collection link.</strong> No account or password is needed to view progress.</li><li><strong>The responsible officer signs in.</strong> Officers add names, record payments and reconcile receipts.</li><li><strong>Pay using the group's instructions.</strong> Give the officer your payment reference; the officer confirms the receipt.</li><li><strong>Follow the updates.</strong> The member page refreshes while it is open.</li><li><strong>Review spending and savings.</strong> Cash, invested capital and loans are kept separate.</li></ol><p>The link can be forwarded. Individual names appear only with recorded consent. Keep your officer password private.</p>`,async()=>{},'Done')}

function render(){account();if(publicId)return renderPublic();if(!config.ready)return setupScreen();if(!session)return welcome();if(openId&&!selected())openId=null;if(!openId)return dashboard();detail()}
function setupScreen(){$('#app').innerHTML=`<div class="card"><span class="pill">Shared service awaiting connection</span><h1 style="margin-top:18px">Sungira is ready for setup.</h1><p>The account and shared group features need the database connection before people can use them.</p><p class="muted">The organiser should follow the setup guide included in the download. Visitors do not need to configure anything.</p><a class="button" href="local.html">Open the existing device ledger</a></div><div class="card" style="margin-top:20px"><h2>Charles Luanga Paper Sunday</h2><p>29 contributor names prepared from the attached programme. No pledges or payments have been assumed.</p><p class="muted">Kanike appears twice in the programme and is included once. Names remain private until consent is recorded.</p></div>`;$('#connection').textContent='Not connected to the shared database.'}
function welcome(){$('#app').innerHTML=`<div class="card"><span class="pill">Churches · Families · Savings groups · Causes</span><h1 style="margin-top:18px">Contribute together. See the progress.</h1><p>Keep contributions, confirmed receipts, and spending in one shared record.</p><div class="actions"><button class="primary" id="start">Create officer account</button><button id="existing">Officer sign in</button></div><p class="muted" style="margin-top:20px">Group members: open the viewing link supplied by your officer. No account is needed.</p></div>`;$('#start').onclick=()=>accountForm(true);$('#existing').onclick=()=>accountForm()}
function dashboard(){const ts=groups.reduce((a,g)=>{const t=totals(g.data);a.collected+=t.collected;a.balance+=t.balance;return a},{collected:0,balance:0});$('#app').innerHTML=`<div class="row"><div><h1>My collections</h1><p class="muted">Manage records here and share a viewing link with the group.</p></div><button class="primary" id="create">＋ Start a collection</button></div><div class="stats">${stat('Confirmed contributions',ts.collected)}${stat('Available balance',ts.balance)}<div class="stat"><span>Your collections</span><strong>${groups.length}</strong></div><div class="stat"><span>Payments awaiting review</span><strong>${groups.reduce((s,g)=>s+g.data.ledger.filter(e=>e.status==='Pending').length,0)}</strong></div></div><div class="toolbar"><input id="search" aria-label="Find a collection" placeholder="Find a collection"><button id="refresh">Refresh now</button></div><div class="grid" id="groups"></div>${config.seedAllowed?'<div class="card" style="margin-top:20px"><h2>Charles Luanga Paper Sunday</h2><p>Start the church collection with the 29 names from your attached list. You can edit the spelling before publishing.</p><button id="seed">Create with the church list</button><small class="muted">Each click creates a new collection. Use this once.</small></div>':''}`;const draw=()=>{$('#groups').innerHTML=groups.filter(g=>g.data.name.toLowerCase().includes($('#search').value.toLowerCase())).map(g=>{const d=g.data,t=totals(d);return `<article class="card"><div class="row"><span class="pill">${esc(d.type)}</span><span class="muted">${esc(g.role)}</span></div><h3>${esc(d.name)}</h3><strong>${money(t.collected)}</strong><small class="muted">Confirmed contributions · ${d.members.length} people</small><div class="bar"><i style="width:${t.target?Math.min(100,t.collected/t.target*100):0}%"></i></div><p class="muted">${esc(d.status)} · Ends ${esc(d.due)}</p><button data-open="${g.id}">Open collection</button></article>`}).join('')||'<div class="card"><p>No collections yet. Start one or ask the organiser to add your account email.</p></div>';document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{openId=b.dataset.open;view='people';render()})};$('#search').oninput=draw;draw();$('#create').onclick=()=>createCollection();$('#seed')?.addEventListener('click',()=>createCollection(true));$('#refresh').onclick=async()=>{try{await sync();render()}catch(e){toast(e.message)}}}
function createCollection(seed=false){modal(seed?'Charles Luanga Paper Sunday':'Start your collection',field('name','Collection name','text',seed?'Charles Luanga Paper Sunday':'','required maxlength="120"')+choice('type','Collection use',types,seed?'Church':'Other')+`<p id="templateExplain" class="muted"></p>`+`<div class="split">${field('start','Start date','date',today(),'required')}${field('due','Deadline','date','','required')}</div><div class="split">${field('target','Overall target (MK)','number','0','required min="0" step="0.01"')}${field('each','Default pledge (MK)','number','0','required min="0" step="0.01"')}</div>`+field('note','Private payment instructions','text','','placeholder="Group bank / Airtel / Mpamba details"')+field('publicNote','Description for members','text','','placeholder="What this collection will fund"')+field('publicPaymentInfo','Payment instructions for members (optional)','text','','placeholder="Account / mobile money details you want to share"')+field('publicContact','Officer contact for members (optional)','text','')+check('isPublic','Enable the unique viewing link for members; no member accounts needed.',true)+choice('cycle','Savings group frequency',['Not applicable','Weekly','Every two weeks','Monthly'])+`<p class="muted">Only the officer signs in to manage records. Member names remain private until consent is recorded. ${seed?'Names are prefilled; pledges and payments start at zero.':''}</p>`,async d=>{if(d.due<d.start)throw Error('The deadline must be on or after the start date.');const out=await api('create',{...d,isPublic:!!d.isPublic,...(seed?{seed:'charles'}:{})});openId=out.id;view='people';toast('Collection created')},'Create collection');const explain=()=>{$('#templateExplain').textContent=planTypes[$('#f-type').value]?.help||({'Investment savings':'Pool contributions, record capital invested and returned cash, and show capital still at risk.','Member lending':'Record member loans at an agreed flat-term or simple-monthly rate and track repayments.'}[$('#f-type').value]||'Track people, contributions, spending and the closing report.')};$('#f-type').onchange=explain;explain()}
function detail(){const g=selected(),d=g.data,t=totals(d),editable=canManage(g)&&d.status==='Open';$('#app').innerHTML=`<button id="back">My collections</button><div class="row" style="margin-top:20px"><div><span class="pill">${esc(d.type)} · ${esc(g.role)} · ${esc(d.status)}</span><h1 style="margin-top:14px">${esc(d.name)}</h1><p class="muted">${esc(d.start)} to ${esc(d.due)}</p></div><div class="actions">${g.role==='Owner'?'<button id="settings">Settings & public view</button><button id="access">Group access</button>':''}<button id="publicLink">Member viewing link</button></div></div>${d.note?`<div class="notice"><strong>Where to pay</strong><br>${esc(d.note)}</div>`:''}<div class="stats">${stat('Confirmed contributions',t.collected)}${stat('Operating spending / payouts',t.spent)}${stat('Cash available',t.balance)}${stat('Awaiting confirmation',t.pending)}</div>${d.status==='Open'&&d.due<today()?'<div class="notice">The collection period has ended. Open Reports to review the expenditure statement and close the collection.</div>':''}<div class="actions">${d.status==='Open'&&canManage(g)?'<button class="primary" id="payment">Record contribution</button>':''}${editable?'<button id="expense">Record expense</button>':''}${d.status==='Open'&&canManage(g)&&config.paymentCollection===g.id?'<button class="primary" id="onlinePay">Pay online</button>':''}<button id="summary">Share totals</button></div><nav class="tabs">${['people','payments','spending',...(planTypes[d.type]?['plans']:[]),...(['Investment savings','Member lending','Banki mkhonde'].includes(d.type)?['savings']:[]),'report','activity'].map(v=>`<button data-view="${v}" class="${view===v?'active':''}">${({people:'People',payments:'Payments',spending:'Spending',plans:'Plans & delivery',savings:'Savings & loans',report:'Reports',activity:'Activity'})[v]}</button>`).join('')}</nav><section id="content"></section>`;$('#back').onclick=()=>{openId=null;render()};$('#settings')?.addEventListener('click',settings);$('#access')?.addEventListener('click',access);$('#publicLink')?.addEventListener('click',memberLink);$('#summary').onclick=()=>share(`${d.name}\nConfirmed: ${money(t.collected)}\nSpent: ${money(t.spent)}\nBalance: ${money(t.balance)}\nDeadline: ${d.due}`);$('#payment')?.addEventListener('click',()=>entry('Contribution'));$('#onlinePay')?.addEventListener('click',onlinePay);$('#expense')?.addEventListener('click',()=>entry('Expense'));document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});({people:people,payments:payments,spending:spending,plans:plans,savings:savings,report:report,activity:activity})[view](g)}
function people(g){const d=g.data;$('#content').innerHTML=`<div class="card"><div class="row"><h2>People & pledges</h2>${canManage(g)&&d.status==='Open'?'<button id="addPerson">Add a person</button>':''}</div><input id="findPerson" placeholder="Find a name" aria-label="Find a name"><div class="table"><table><thead><tr><th>Name</th><th>Pledged</th><th>Confirmed</th><th>Outstanding</th><th>Action</th></tr></thead><tbody id="peopleRows"></tbody></table></div><p class="muted">Contributor names are private unless that person agrees to appear publicly. Family entries remain together as provided in the list.</p></div>${d.type==='Banki mkhonde'?`<div class="card" style="margin-top:20px"><h2>Rotation</h2><p>${esc(d.cycle)}</p>${d.members.map((m,i)=>`<p>${i+1}. ${esc(m.name)}${i===d.turn%d.members.length?' · Current recipient':''}</p>`).join('')}${canManage(g)&&d.status==='Open'&&d.members.length?'<button id="turn">Move to next recipient</button>':''}<p class="muted">Moving the turn does not record a payout. Record the payout under Spending.</p></div>`:''}`;const draw=()=>{$('#peopleRows').innerHTML=d.members.filter(m=>m.name.toLowerCase().includes($('#findPerson').value.toLowerCase())).map(m=>`<tr><td><strong>${esc(m.name)}</strong><small>${esc(m.phone||'')}</small></td><td>${money(m.pledge)}</td><td>${money(paid(d,m))}</td><td>${money(Math.max(0,m.pledge-paid(d,m)))}</td><td>${canManage(g)&&d.status==='Open'?`<button data-edit="${m.id}">Edit</button>`:''}</td></tr>`).join('')||'<tr><td colspan="5">No matching people.</td></tr>';document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>person(b.dataset.edit))};$('#findPerson').oninput=draw;draw();$('#addPerson')?.addEventListener('click',()=>person());$('#turn')?.addEventListener('click',async()=>{try{await api('turn',{id:g.id});await sync();render()}catch(e){toast(e.message)}})}
function person(id){const g=selected(),m=g.data.members.find(m=>m.id===id)||{};modal(id?'Edit contributor':'Add contributor',field('name','Name','text',m.name||'','required maxlength="120"')+field('phone','Phone (optional)','tel',m.phone||'')+field('pledge','Pledged amount (MK)','number',m.pledge??g.data.each,'min="0" step="0.01" required')+check('publicConsent','This person has agreed to show their name and confirmed total on the public page.',m.publicConsent),async d=>{await api('person',{...d,id:g.id,member:id||'',publicConsent:!!d.publicConsent});toast('Contributor saved')})}
async function access(){const g=selected();try{const list=await api('access_list',{id:g.id});modal('Share group access',`<p>Members need only the member viewing link. Use this form to give another officer or reviewer access to the private records. No invitation email is sent automatically.</p>${field('email','Their account email','email','','required')}${choice('role','What can they do?',['Treasurer','Viewer'])}<p class="muted">Viewer: a read-only reviewer. Treasurer: manage names, confirm payments and record expenses. Only the owner controls account access and public visibility.</p><h3>Current access</h3>${list.map(a=>`<p>${esc(a.email)} · ${esc(a.role)} <button type="button" data-revoke="${esc(a.email)}">Remove</button></p>`).join('')||'<p>No other accounts added yet.</p>'}`,async d=>{await api('grant',{id:g.id,...d});toast('Access added. Ask them to sign in with that email.')},'Add access');document.querySelectorAll('[data-revoke]').forEach(b=>b.onclick=async()=>{if(!confirm('Remove access for '+b.dataset.revoke+'?'))return;try{await api('revoke',{id:g.id,email:b.dataset.revoke});$('#dialog').close();await access()}catch(e){toast(e.message)}})}catch(e){toast(e.message)}}
function settings(){const g=selected(),d=g.data;modal('Collection settings',field('name','Collection name','text',d.name,'required maxlength="120"')+field('due','Deadline','date',d.due,'required')+field('target','Overall target (MK)','number',d.target,'min="0" step="0.01" required')+field('note','Private payment instructions','text',d.note)+field('publicNote','Description for members','text',d.publicNote)+field('publicPaymentInfo','Payment instructions visible to link readers','text',d.publicPaymentInfo||'')+field('publicContact','Officer contact visible to link readers','text',d.publicContact||'')+check('isPublic','Enable the member viewing link. Anyone with the link can view the published information.',d.isPublic)+`<p class="muted">Members see confirmed totals, spending categories and aggregate savings balances. Phone numbers, payment references, proof pictures and account emails stay private. Names appear only where consent is recorded.</p>`,async values=>{await api('settings',{...values,id:g.id,start:d.start,isPublic:!!values.isPublic});toast('Settings saved')})}
function entry(kind,planId=''){const g=selected(),d=g.data,contribution=kind==='Contribution',requestId=crypto.randomUUID();if(contribution&&!d.members.length){toast('Ask the treasurer to add your name first.');return}modal(contribution?'Tell us about the payment':'Record an expense or payout',`${contribution?`<label for="f-member">Who contributed?</label><select id="f-member" name="member">${d.members.map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select><p class="muted">Record the member's payment, then review it against the group's statement or cash receipt.</p>`:choice('kind','Entry type',['Expense','Mkhonde payout'],kind)+field('payee','Who was paid?','text','','required')+choice('category','What was it for?',['Transport','Food & refreshments','Materials / project','Venue','Welfare','Fees','Rotation payout','Other'])}${!contribution&&g.data.plans?.length?`<label for="f-plan">Link to a planned item (optional)</label><select id="f-plan" name="plan"><option value="">General expense</option>${g.data.plans.filter(pl=>pl.status==='Planned').map(pl=>`<option value="${pl.id}" ${pl.id===planId?'selected':''}>${esc(pl.title)}</option>`).join('')}</select>`:''}${field('amount','Amount paid (MK)','number','','min="0.01" max="100000000000" step="0.01" required')}${field('date','Payment date','date',today(),`required min="${d.start}" max="${today()}"`)}${choice('method','How did you pay?',['Cash','Airtel Money','TNM Mpamba','Bank transfer','Other'])}${field('ref','Transaction or receipt reference','text','','placeholder="Required except for cash" maxlength="120"')}${field('note',contribution?'Note (optional)':'Purpose of the expense','text','',contribution?'maxlength="500"':'required maxlength="500"')}${field('attachment','Payment proof / receipt picture (optional, up to 200 KB)','file','','accept="image/png,image/jpeg,image/webp"')}<p class="muted">${contribution?'The payment stays Pending until the treasurer confirms receipt. A screenshot alone does not verify a transfer.':'An expense reduces the available balance immediately. Record money already spent, not planned spending.'}</p>`,async(values,form)=>{const file=form.querySelector('[name=attachment]').files[0];let attachment='';if(file){if(file.size>200*1024)throw Error('Choose a picture smaller than 200 KB.');attachment=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('The picture could not be read.'));r.readAsDataURL(file)})}await api('entry',{...values,kind:contribution?'Contribution':values.kind,id:g.id,attachment,requestId});toast(contribution?'Payment submitted. Waiting for treasurer confirmation.':'Expense recorded')},contribution?'Submit payment':'Save expense')}
function entryRows(g,items){const d=g.data;return items.map(e=>`<tr><td>${esc(e.date)}<small>${e.id.slice(0,8)}</small></td><td><strong>${esc(e.kind==='Contribution'?d.members.find(m=>m.id===e.member)?.name:e.payee)}</strong><small>${esc(e.note)}</small></td><td>${money(e.amount)}<small>${esc(e.method)} · ${esc(e.ref)}</small></td><td><span class="pill">${esc(e.status)}</span><small>${esc(e.verification||'Awaiting treasurer review')}</small></td><td><div class="actions"><button data-receipt="${e.id}">Details</button>${e.providerPending&&e.reportedBy===session?.user?.email?`<button data-verify="${esc(e.ref)}">Check payment</button>`:''}${canManage(g)&&d.status==='Open'&&e.status==='Pending'&&!e.providerPending?`<button data-review="${e.id}">Review</button>`:''}${canManage(g)&&d.status==='Open'&&e.status==='Confirmed'?`<button data-void="${e.id}">Void</button>`:''}</div></td></tr>`).join('')||'<tr><td colspan="5">No entries yet.</td></tr>'}
function payments(g){$('#content').innerHTML=`<div class="card"><h2>Payments</h2><p class="muted">Confirmed payments count toward the total. Pending and rejected payments do not.</p><div class="toolbar"><select id="paymentFilter" aria-label="Payment status"><option>All payments</option><option>Pending</option><option>Confirmed</option><option>Rejected</option><option>Voided</option></select></div><div class="table"><table><thead><tr><th>Date</th><th>Contributor</th><th>Amount / reference</th><th>Status</th><th>Action</th></tr></thead><tbody id="paymentsRows"></tbody></table></div></div>`;const draw=()=>{$('#paymentsRows').innerHTML=entryRows(g,g.data.ledger.filter(e=>e.kind==='Contribution'&&($('#paymentFilter').value==='All payments'||e.status===$('#paymentFilter').value)));bindEntries(g)};$('#paymentFilter').onchange=draw;draw()}
function spending(g){$('#content').innerHTML=`<div class="card"><h2>Spending & payouts</h2><div class="table"><table><thead><tr><th>Date</th><th>Paid to / purpose</th><th>Amount / reference</th><th>Status</th><th>Action</th></tr></thead><tbody>${entryRows(g,g.data.ledger.filter(e=>['Expense','Mkhonde payout'].includes(e.kind)))}</tbody></table></div></div>`;bindEntries(g)}
function bindEntries(g){document.querySelectorAll('[data-verify]').forEach(b=>b.onclick=async()=>{try{const out=await paymentAPI('verify',{tx_ref:b.dataset.verify});toast(out.ok?'Provider confirmed the payment':out.message);await sync();render()}catch(e){toast(e.message)}});document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>review(b.dataset.review));document.querySelectorAll('[data-void]').forEach(b=>b.onclick=()=>modal('Void an entry',field('reason','Why is this entry being voided?','text','','required minlength="3"')+'<p>The original record stays in the ledger. Confirmed totals will be recalculated.</p>',async d=>{await api('void',{id:g.id,entry:b.dataset.void,...d});toast('Entry voided')}));document.querySelectorAll('[data-receipt]').forEach(b=>b.onclick=()=>entryDetail(g,b.dataset.receipt))}
async function review(id){const g=selected(),e=g.data.ledger.find(e=>e.id===id);try{if(e.hasAttachment)e.attachment=(await api('proof',{id:g.id,entry:id})).attachment}catch(err){toast(err.message);return}const name=g.data.members.find(m=>m.id===e.member)?.name;modal('Check and confirm payment',`<h3>${esc(name)} · ${money(e.amount)}</h3><p>${esc(e.method)} · ${esc(e.ref||'No reference')} · ${esc(e.date)}</p>${e.attachment?`<img src="${esc(e.attachment)}" class="proof" alt="Submitted payment proof">`:''}<div class="notice">Check the group bank / mobile money statement or cash receipt. Confirm the amount, reference and sender. A screenshot is supporting evidence.</div>${choice('decision','Decision',['Confirmed','Rejected'])}${field('reason','How did you check it / reason for rejection?','text','','required minlength="3" placeholder="e.g. Matched Mpamba statement reference"')}`,async d=>{await api('review',{...d,id:g.id,entry:id});toast('Payment review saved')},'Save decision')}
async function entryDetail(g,id){const e=g.data.ledger.find(e=>e.id===id);try{if(e.hasAttachment)e.attachment=(await api('proof',{id:g.id,entry:id})).attachment}catch(err){toast(err.message);return}const name=e.kind==='Contribution'?g.data.members.find(m=>m.id===e.member)?.name:e.payee;modal('Entry details',`<span class="pill">${esc(e.status)}</span><h3>${esc(name)} · ${money(e.amount)}</h3><p>${esc(e.date)} · ${esc(e.method)}<br>Reference: ${esc(e.ref||'Not supplied')}<br>${esc(e.note)}</p><p class="muted">Reported by: ${esc(e.reportedBy)}<br>Review: ${esc(e.reviewNote||'Not reviewed')}<br>Reviewed by: ${esc(e.reviewedBy||'Not yet reviewed')}<br>${esc(e.voidReason||'')}<br>ID: ${e.id}</p>${e.attachment?`<img src="${esc(e.attachment)}" class="proof" alt="Payment proof or expense receipt">`:''}<button type="button" id="receiptShare">Share receipt text</button>`,async()=>{},'Done');$('#receiptShare').onclick=()=>share(`${g.data.name}\n${e.status} ${e.kind}: ${name}\n${money(e.amount)} · ${e.date}\nMethod: ${e.method}; reference: ${e.ref||'not supplied'}\n${e.verification||'Pending review'}\nReceipt ID: ${e.id}`)}
function reportHTML(g){const d=g.data,t=totals(d),expenses=d.ledger.filter(e=>['Expense','Mkhonde payout'].includes(e.kind)&&e.status==='Confirmed');return `<article class="report"><span class="pill">${d.status==='Closed'||d.due<today()?'End-of-period':'Interim'} report</span><h1 style="margin-top:18px">${esc(d.name)}</h1><p>Period: ${esc(d.start)} – ${esc(d.due)}<br>Prepared: ${today()} · ${esc(d.status)}</p><div class="stats">${stat('Confirmed contributions',t.collected)}${stat('Confirmed spending',t.spent)}${stat('Closing balance',t.balance)}</div><p>Cash receipts ${money(sum(d.ledger.filter(e=>e.status==='Confirmed'&&['Contribution','Loan repayment','Investment proceeds'].includes(e.kind))))} − cash outflows ${money(sum(d.ledger.filter(e=>e.status==='Confirmed'&&['Expense','Mkhonde payout','Loan disbursement','Investment placement'].includes(e.kind))))} = cash ${money(t.balance)}.</p><p class="muted">Pending ${money(t.pending)} is excluded. Includes late entries assigned to this collection. Treasurer-reviewed and provider-verified payments are labelled separately in the ledger. This is not an independent audit.</p><h2>Savings position</h2><p>Capital in investments: ${money(t.investmentBook)} · Outstanding loan principal: ${money(t.loanPrincipal)} · Cash plus principal assets: ${money(t.assets)}</p><p>Loan interest received: ${money(t.interestReceived)} · Realised investment gain/loss: ${money(t.investmentGain)} · Loan principal written off: ${money(t.loanWriteoffs)}</p><p class="muted">Outstanding loans and investment cost balances are not guaranteed recoverable. Unreceived interest and estimated investment gains are excluded from received income.</p>${financeReport(d)}<h2>Contributors</h2><div class="table"><table><thead><tr><th>Name</th><th>Pledged</th><th>Confirmed</th><th>Outstanding</th></tr></thead><tbody>${d.members.map(m=>`<tr><td>${esc(m.name)}</td><td>${money(m.pledge)}</td><td>${money(paid(d,m))}</td><td>${money(Math.max(0,m.pledge-paid(d,m)))}</td></tr>`).join('')}</tbody></table></div><h2>Expenditure statement</h2><div class="table"><table><thead><tr><th>Date</th><th>Recipient</th><th>Category / purpose</th><th>Reference</th><th>Amount</th></tr></thead><tbody>${expenses.map(e=>`<tr><td>${esc(e.date)}</td><td>${esc(e.payee)}</td><td>${esc(e.category)}<small>${esc(e.note)}</small></td><td>${esc(e.ref)}</td><td>${money(e.amount)}</td></tr>`).join('')||'<tr><td colspan="5">No expenditure recorded.</td></tr>'}</tbody></table></div><h2>Spending by category</h2>${[...new Set(expenses.map(e=>e.category))].map(c=>`<p>${esc(c)}: ${money(sum(expenses.filter(e=>e.category===c)))}</p>`).join('')||'<p>No expenditure recorded.</p>'}<p style="margin-top:40px">Prepared by: ____________________ &nbsp; Reviewed by: ____________________</p><p>Cash / bank / mobile money balance reconciled on: ____________________</p></article>`}
function report(g){$('#content').innerHTML=`<div class="toolbar"><button id="print" class="primary">Print / save PDF</button><button id="csv">Download ledger CSV</button><button id="html">Download report</button>${canManage(g)?`<button id="close">${g.data.status==='Closed'?'Reopen collection':'Close collection'}</button>`:''}</div>${reportHTML(g)}`;$('#print').onclick=()=>window.print();$('#html').onclick=()=>download('sungira-report.html','<!doctype html><html lang="en"><meta charset="utf-8"><title>Expenditure report</title><style>body{font:16px/1.5 system-ui;max-width:1100px;margin:40px auto;padding:20px}table{width:100%;border-collapse:collapse}td,th{padding:10px;text-align:left;border-bottom:1px solid #ccc}small{display:block}.stats{display:flex;gap:30px}.stat strong{display:block}</style>'+reportHTML(g)+'</html>','text/html');$('#csv').onclick=()=>{const cell=v=>'"'+String(v??'').replace(/"/g,'""').replace(/^[=+@-]/,"'")+'"';download('sungira-ledger.csv','\ufeff'+[['ID','Date','Type','Name / recipient','Amount MK','Method','Reference','Status','Verification','Review note','Reported by','Principal received','Interest received','Capital cost released','Principal written off','Interest waived','Plan ID'],...g.data.ledger.map(e=>[e.id,e.date,e.kind,e.kind==='Contribution'?g.data.members.find(m=>m.id===e.member)?.name:e.payee,e.amount,e.method,e.ref,e.status,e.verification,e.reviewNote,e.reportedBy,e.principalPaid,e.interestPaid,e.basisReleased,e.principalWrittenOff,e.interestWaived,e.plan])].map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8')};$('#close')?.addEventListener('click',async()=>{if(!confirm(g.data.status==='Closed'?'Reopen this collection?':'Have you checked the entries and reconciled the balance? Closing locks financial entries.'))return;try{await api('close',{id:g.id});await sync();render()}catch(e){toast(e.message)}})}
function activity(g){$('#content').innerHTML=`<div class="card"><h2>Activity</h2><p class="muted">Changes are recorded by the server. Group users cannot edit this history. Database administrators still control the underlying database.</p>${g.data.audit.map(a=>`<p><small class="muted">${esc(new Date(a.at).toLocaleString())} · ${esc(a.actor)}</small>${esc(a.text)}</p>`).join('')}</div>`}
function share(text){window.open('https://wa.me/?text='+encodeURIComponent(text),'_blank','noopener,noreferrer')}
function renderPublic(){const d=publicData;account();if(!d){$('#app').innerHTML='<div class="card"><h1>Collection unavailable</h1><p>The collection may be private or its link may have been replaced. Ask your officer for the latest member link.</p><a class="button" href="./">Go to Sungira</a></div>';return}$('#app').innerHTML=`<span class="pill">Member viewing page · ${esc(d.status)}</span><p class="muted">No account needed. Save this link to follow your collection.</p><h1 style="margin-top:18px">${esc(d.name)}</h1><p>${esc(d.note||'')}</p><p class="muted">${esc(d.type)} · Deadline ${esc(d.due)} · ${d.headcount} contributors</p><div class="stats">${stat('Confirmed contributions',d.collected)}${stat('Operating spending / payouts',d.spent)}${stat('Cash available',d.balance)}${stat('Collection target',d.target)}</div>${d.finance&&(Number(d.finance.investmentBook)>0||Number(d.finance.loanPrincipal)>0||['Investment savings','Member lending','Banki mkhonde'].includes(d.type))?`<div class="stats">${stat('Capital in investments',d.finance.investmentBook)}${stat('Outstanding loan principal',d.finance.loanPrincipal)}${stat('Cash + principal assets',d.finance.assets)}${stat('Loan interest received',d.finance.interestReceived)}</div><p class="muted">Invested capital and loan principal are not available cash. Scheduled interest is not counted as received income.</p>`:''}<div class="card"><h2>Contributions</h2><p class="muted">Names are shown with consent. Totals include confirmed payments from all contributors.</p><div class="table"><table><thead><tr><th>Contributor</th><th>Confirmed contribution</th></tr></thead><tbody>${d.members.map(m=>`<tr><td>${esc(m.name)}</td><td>${money(m.paid)}</td></tr>`).join('')||'<tr><td colspan="2">No individual names have been published. Confirmed totals are shown above.</td></tr>'}</tbody></table></div></div>${d.plans?.length?`<div class="card" style="margin-top:20px"><h2>Plans & delivery</h2>${d.plans.map(pl=>`<p><strong>${esc(pl.title)}</strong> · ${esc(pl.status)}<small>Planned cost ${money(pl.budget)} · Due ${esc(pl.due)}</small></p>`).join('')}</div>`:''}<div class="card" style="margin-top:20px"><h2>Expenditure summary</h2><div class="table"><table><thead><tr><th>Date</th><th>Category</th><th>Amount</th></tr></thead><tbody>${d.expenses.map(e=>`<tr><td>${esc(e.date)}</td><td>${esc(e.category)}</td><td>${money(e.amount)}</td></tr>`).join('')||'<tr><td colspan="3">No confirmed expenditure.</td></tr>'}</tbody></table></div><p class="muted">Confirmed means checked by the group treasurer. PayChangu checkout payments are verified by the provider when connected; other payments are checked by the treasurer.</p><button id="publicPrint">Print / save PDF</button></div><div class="actions">${d.paymentInfo?`<div class="notice"><strong>How to contribute</strong><br>${esc(d.paymentInfo)}${d.officerContact?`<p>Officer contact: ${esc(d.officerContact)}</p>`:''}</div>`:''}<button id="copyLink">Copy this viewing link</button></div>`;$('#publicPrint').onclick=()=>window.print();$('#copyLink').onclick=()=>copyText(location.href)}
async function paymentAPI(action,data){const r=await fetch('/.netlify/functions/payment',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+await accessToken()},body:JSON.stringify({action,...data})});const out=await r.json();if(!r.ok)throw Error(out.error||'Unable to check payment.');return out}
function onlinePay(){const g=selected();if(!g.data.members.length){toast('Add a contributor before paying.');return}modal('Pay through PayChangu',`<label for="f-member">Contributor</label><select id="f-member" name="member">${g.data.members.map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select>${field('amount','Amount (MK)','number','','required min="1" step="0.01"')}<div class="notice">Merchant receiving the payment: <strong>${esc(config.merchantName)}</strong>. Proceed only if this is the intended account for this group.</div><p>The provider collects payment on its secure page. Payment charges are recorded separately. Provider-held funds must be reconciled with the merchant statement.</p>`,async d=>{const out=await paymentAPI('checkout',{id:g.id,...d});location.href=out.checkout_url},'Continue to payment')}
const planTypes={
 'Emergency welfare fund':{kind:'Welfare case',label:'Welfare cases',title:'Beneficiary / request (private)',help:'Plan emergency assistance, record the approved amount and track payment or delivery.'},
 'School-fee support':{kind:'School fee',label:'School-fee commitments',title:'Learner / school / term (private)',help:'Track fees due, planned support, payments and completion for each learner or term.'},
 'Community project':{kind:'Project milestone',label:'Project milestones',title:'Milestone / work package',help:'Set a budget and date for each stage, link actual expenditure and report delivery.'},
 'Bulk purchasing':{kind:'Purchase order',label:'Purchase orders',title:'Item / order description',help:'Record quantities and unit costs, pool orders, link supplier payments and mark deliveries.'},
 'Event / trip fund':{kind:'Event booking',label:'Event / trip bookings',title:'Booking / cost item',help:'Plan seats, meals, tickets or accommodation using quantity × unit cost, then record actual spending.'}
};
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('Link copied. Send it to your group.')}catch{window.prompt('Copy this link and send it to your group:',text)}}
function viewingLink(g){return location.origin+location.pathname+'?collection='+g.id+'&token='+g.data.publicToken}
function memberLink(){const g=selected(),d=g.data;if(!d.publicToken){toast('The database update is needed before new member links can be created.');return}if(!d.isPublic){toast('Enable member viewing under Settings & public view first.');return}const link=viewingLink(g);modal('One link for your members',`<p>Members open this link to see this collection. They do not register or enter a password.</p>${field('link','Member viewing link','text',link,'readonly')}<div class="actions"><button type="button" id="copyMember">Copy link</button><button type="button" id="whatsMember">Send on WhatsApp</button></div><p class="muted">Anyone with this link can view the published information and forward the link. Keep personal loan details and sensitive beneficiary names private.</p>${g.role==='Owner'?'<button type="button" id="replaceLink">Replace link and disable the old one</button>':''}`,async()=>{},'Done');$('#copyMember').onclick=()=>copyText(link);$('#whatsMember').onclick=()=>share(`${d.name}\nOpen our collection here — no account needed:\n${link}`);$('#replaceLink')?.addEventListener('click',async()=>{if(!confirm('Replace the viewing link? The old link will stop working. Send the new link to every member.'))return;try{await api('rotate_link',{id:g.id});$('#dialog').close();await sync();memberLink()}catch(e){toast(e.message)}})}
function planSpend(d,id){return sum(d.ledger.filter(e=>e.status==='Confirmed'&&e.plan===id))}
function plans(g){const d=g.data,template=planTypes[d.type],items=d.plans||[];$('#content').innerHTML=`<div class="card"><div class="row"><h2>${template.label}</h2>${canManage(g)&&d.status==='Open'?'<button class="primary" id="newPlan">Add planned item</button>':''}</div><p class="muted">${template.help} A plan does not move money.</p><div class="stats">${stat('Planned costs',items.filter(pl=>pl.status!=='Cancelled').reduce((s,pl)=>s+Number(pl.budget),0))}${stat('Linked actual spending',items.reduce((s,pl)=>s+planSpend(d,pl.id),0))}<div class="stat"><span>Completed</span><strong>${items.filter(pl=>pl.status==='Completed').length} / ${items.filter(pl=>pl.status!=='Cancelled').length}</strong></div></div>${items.map(pl=>`<article class="plan-row"><div class="row"><h3>${esc(pl.title)}</h3><span class="pill">${esc(pl.status)}</span></div><p>Budget ${money(pl.budget)} · Spent ${money(planSpend(d,pl.id))} · Due ${esc(pl.due)}${pl.status==='Planned'&&pl.due<today()?' · Due date passed':''}</p>${pl.quantity?`<p>${esc(pl.quantity)} × ${money(pl.unitCost)} ${pl.member?' · '+esc(d.members.find(m=>m.id===pl.member)?.name||''):''}</p>`:''}<p class="muted">${esc(pl.note||'')}</p>${canManage(g)&&d.status==='Open'?`<div class="actions"><button data-plan-edit="${pl.id}">Edit plan</button>${pl.status==='Planned'?`<button data-plan-pay="${pl.id}">Record linked expense</button><button data-plan-complete="${pl.id}">Mark delivered / completed</button><button data-plan-cancel="${pl.id}">Cancel</button>`:`<button data-plan-reopen="${pl.id}">Reopen plan</button>`}</div>`:''}</article>`).join('')||'<p>No planned items yet. Add your first commitment or cost item.</p>'}</div>`;$('#newPlan')?.addEventListener('click',()=>planForm());document.querySelectorAll('[data-plan-edit]').forEach(b=>b.onclick=()=>planForm(b.dataset.planEdit));document.querySelectorAll('[data-plan-pay]').forEach(b=>b.onclick=()=>entry('Expense',b.dataset.planPay));const setStatus=(selector,key,status)=>document.querySelectorAll(selector).forEach(b=>b.onclick=async()=>{if(!confirm('Mark this item '+status.toLowerCase()+'? This records delivery status and does not move money.'))return;try{await api('plan_status',{id:g.id,plan:b.dataset[key],status});await sync();render()}catch(e){toast(e.message)}});setStatus('[data-plan-complete]','planComplete','Completed');setStatus('[data-plan-cancel]','planCancel','Cancelled');setStatus('[data-plan-reopen]','planReopen','Planned')}
function planForm(id){const g=selected(),cfg=planTypes[g.data.type],pl=(g.data.plans||[]).find(pl=>pl.id===id)||{},quantityBased=['Purchase order','Event booking'].includes(cfg.kind);modal(id?'Update planned item':'Add '+cfg.kind.toLowerCase(),field('title',cfg.title,'text',pl.title||'','required maxlength="120"')+(quantityBased?`<div class="split">${field('quantity','Quantity / number of places','number',pl.quantity||1,'required min="1" step="1"')}${field('unitCost','Cost per item / place (MK)','number',pl.unitCost||0,'required min="0" step="0.01"')}</div>`:'')+field('budget','Planned total cost (MK)','number',pl.budget||0,`required min="0" step="0.01" ${quantityBased?'readonly':''}`)+(quantityBased?`<label for="f-member">Person / order owner (optional)</label><select id="f-member" name="member"><option value="">Group order</option>${g.data.members.map(m=>`<option value="${m.id}" ${m.id===pl.member?'selected':''}>${esc(m.name)}</option>`).join('')}</select>`:'')+field('due','Due / delivery date','date',pl.due||'','required')+field('note','Private note / approval reference','text',pl.note||'')+field('publicTitle','Label for members to see (optional)','text',pl.publicTitle||'','placeholder="e.g. Roofing stage, term fees, bus booking"')+'<p class="muted">Leave the public label empty to keep this item private. Avoid beneficiary names or personal circumstances in public labels.</p>',async values=>{await api('plan',{...values,id:g.id,plan:id||'',kind:cfg.kind});toast('Plan saved')});if(quantityBased){const calc=()=>{$('#f-budget').value=(Number($('#f-quantity').value)*Number($('#f-unitCost').value)).toFixed(2)};$('#f-quantity').oninput=calc;$('#f-unitCost').oninput=calc;calc()}}
function activeEvents(d,id){return d.ledger.filter(e=>e.entityId===id&&e.status==='Confirmed')}
function investmentState(d,iv){const a=activeEvents(d,iv.id),active=a.some(e=>e.kind==='Investment placement'),returned=a.filter(e=>e.kind==='Investment proceeds');return{active,remaining:active?Number(iv.amount)-returned.reduce((s,e)=>s+Number(e.basisReleased||0),0):0,cashReturned:sum(returned),gain:returned.reduce((s,e)=>s+Number(e.amount)-Number(e.basisReleased||0),0)}}
function loanState(d,l){const a=activeEvents(d,l.id),active=a.some(e=>e.kind==='Loan disbursement'),principalPaid=a.reduce((s,e)=>s+Number(e.principalPaid||0),0),interestPaid=a.reduce((s,e)=>s+Number(e.interestPaid||0),0),principalWrittenOff=a.reduce((s,e)=>s+Number(e.principalWrittenOff||0),0),interestWaived=a.reduce((s,e)=>s+Number(e.interestWaived||0),0),principal=active?Number(l.principal)-principalPaid-principalWrittenOff:0,interest=active?Number(l.agreedInterest)-interestPaid-interestWaived:0;const due=(l.schedule||[]).filter(i=>i.due<today());const overdue=active?Math.max(0,due.reduce((s,i)=>s+Number(i.principal),0)-principalPaid-principalWrittenOff)+Math.max(0,due.reduce((s,i)=>s+Number(i.interest),0)-interestPaid-interestWaived):0;return{active,principal,interest,principalPaid,interestPaid,principalWrittenOff,interestWaived,overdue}}
function savings(g){const d=g.data,t=totals(d),investments=d.investments||[],loans=d.loans||[],editable=canManage(g)&&d.status==='Open';$('#content').innerHTML=`<div class="stats">${stat('Cash available',t.balance)}${stat('Capital still invested',t.investmentBook)}${stat('Outstanding loan principal',t.loanPrincipal)}${stat('Cash + principal assets',t.assets)}</div><p class="muted">Assets are recorded at remaining principal/cost, not a guaranteed sale or recovery value. Expected returns and unpaid interest are not available cash.</p>${editable?'<div class="toolbar"><button class="primary" id="placeInvestment">Record investment placement</button><button class="primary" id="newLoan">Record a member loan</button></div>':''}<div class="card"><h2>Group investments</h2>${investments.map(iv=>{const st=investmentState(d,iv);return `<article class="plan-row"><div class="row"><h3>${esc(iv.title)}</h3><span class="pill">${!st.active?'Voided':st.remaining===0?'Capital released':'Active'}</span></div><p>Placed ${money(iv.amount)} · Capital at cost ${money(st.remaining)} · Cash returned ${money(st.cashReturned)} · Realised gain/loss ${money(st.gain)}</p><p class="muted">Review date ${esc(iv.maturity)}${st.remaining>0&&iv.maturity<today()?' · Review due':''}<br>${esc(iv.note||'')}</p>${editable&&st.active?`<button data-return="${iv.id}">Record returned cash / capital</button>`:''}</article>`}).join('')||'<p>No investments recorded.</p>'}</div><div class="card" style="margin-top:20px"><h2>Loans to members</h2><p class="muted">Interest is agreed for a fixed term: a flat percentage for the whole term or simple interest per month on original principal. No compounding, late penalties or automatic early-settlement discounts.</p>${loans.map(l=>{const st=loanState(d,l);return `<article class="plan-row"><div class="row"><h3>${esc(d.members.find(m=>m.id===l.member)?.name||'Borrower')}</h3><span class="pill">${!st.active?'Voided':st.principal+st.interest===0?'Settled':st.overdue>0?'Repayment overdue':'Active'}</span></div><p>Principal ${money(l.principal)} · Agreed rate ${esc(l.rate)}% · ${esc(l.basis)} · ${l.months} months</p><p>Outstanding principal ${money(st.principal)} · Agreed interest outstanding ${money(st.interest)} · Overdue scheduled amount ${money(st.overdue)}</p><small class="muted">Received principal ${money(st.principalPaid)} · Received interest ${money(st.interestPaid)}</small><details><summary>Repayment schedule and agreement</summary><p>${esc(l.note||'No agreement note supplied')}</p><div class="table"><table><thead><tr><th>Due</th><th>Principal</th><th>Interest</th><th>Total</th></tr></thead><tbody>${(l.schedule||[]).map(i=>`<tr><td>${esc(i.due)}</td><td>${money(i.principal)}</td><td>${money(i.interest)}</td><td>${money(Number(i.principal)+Number(i.interest))}</td></tr>`).join('')}</tbody></table></div></details>${editable&&st.active&&st.principal+st.interest>0?`<div class="actions"><button data-repay="${l.id}">Record repayment</button><button data-writeoff="${l.id}">Record approved write-off / waiver</button></div>`:''}</article>`}).join('')||'<p>No loans recorded.</p>'}</div><div class="card" style="margin-top:20px"><h2>Savings transaction ledger</h2><div class="table"><table><thead><tr><th>Date</th><th>Activity</th><th>Cash amount</th><th>Allocation</th><th>Correction</th></tr></thead><tbody>${d.ledger.filter(e=>['Loan disbursement','Loan repayment','Loan adjustment','Investment placement','Investment proceeds'].includes(e.kind)).map(e=>`<tr><td>${esc(e.date)}<small>${e.id.slice(0,8)}</small></td><td>${esc(e.kind)}<small>${esc(e.note)} · ${esc(e.status)}</small></td><td>${money(e.amount)}</td><td>${e.kind==='Loan repayment'?`Principal ${money(e.principalPaid)}<br>Interest ${money(e.interestPaid)}`:e.kind==='Investment proceeds'?`Capital cost released ${money(e.basisReleased)}`:e.kind==='Loan adjustment'?`Principal loss ${money(e.principalWrittenOff)}<br>Interest waived ${money(e.interestWaived)}`:''}</td><td>${editable&&e.status==='Confirmed'?`<button data-reverse="${e.id}">Reverse</button>`:''}</td></tr>`).join('')||'<tr><td colspan="5">No savings transactions yet.</td></tr>'}</tbody></table></div></div>`;$('#placeInvestment')?.addEventListener('click',investmentForm);$('#newLoan')?.addEventListener('click',loanForm);document.querySelectorAll('[data-return]').forEach(b=>b.onclick=()=>investmentReturn(b.dataset.return));document.querySelectorAll('[data-repay]').forEach(b=>b.onclick=()=>repaymentForm(b.dataset.repay));document.querySelectorAll('[data-writeoff]').forEach(b=>b.onclick=()=>repaymentForm(b.dataset.writeoff,true));document.querySelectorAll('[data-reverse]').forEach(b=>b.onclick=()=>modal('Reverse this savings entry',field('reason','Reason for the correction','text','','required minlength="3"')+'<p>The original remains in the history. Principal and cash balances will be recalculated.</p>',async values=>{await api('finance_reverse',{...values,id:g.id,entry:b.dataset.reverse});toast('Savings entry reversed')}))}
function financialFields(note='Private note / agreement reference'){return field('date','Transaction date','date',today(),'required max="'+today()+'"')+choice('method','Payment method',['Cash','Airtel Money','TNM Mpamba','Bank transfer','Other'])+field('ref','Transaction / receipt reference','text','','placeholder="Required except for cash" maxlength="120"')+field('note',note,'text','','maxlength="500"')}
function investmentForm(){const g=selected(),requestId=crypto.randomUUID();modal('Record group capital invested',field('title','Investment / asset name','text','','required maxlength="120" placeholder="e.g. Group maize trading project"')+field('amount','Cash already placed (MK)','number','','required min="0.01" max="100000000000" step="0.01"')+field('maturity','Review / expected return date','date','','required')+financialFields()+'<p>This reduces cash and records capital at cost. It does not initiate an investment or promise a return.</p>',async values=>{await api('investment',{...values,id:g.id,requestId});toast('Investment placement recorded')})}
function investmentReturn(id){const g=selected(),iv=g.data.investments.find(iv=>iv.id===id),st=investmentState(g.data,iv),requestId=crypto.randomUUID();modal('Record investment cash returned',`<h3>${esc(iv.title)}</h3><p>Capital still at cost: ${money(st.remaining)}</p>${field('amount','Actual cash received (MK)','number','','required min="0" step="0.01"')}${field('basisReleased','Original capital cost released (MK)','number','0',`required min="0" max="${st.remaining}" step="0.01"`)}<div id="returnPreview" class="notice"></div>${financialFields()}<p class="muted">Cash minus original capital released is the realised gain or loss. A complete loss can be recorded as zero cash with all remaining capital released. For a profit-only distribution, release zero capital.</p>`,async values=>{await api('investment_return',{...values,id:g.id,entity:id,requestId});toast('Investment return recorded')});const update=()=>$('#returnPreview').textContent='Realised gain / loss: '+money(Number($('#f-amount').value)-Number($('#f-basisReleased').value));$('#f-amount').oninput=update;$('#f-basisReleased').oninput=update;update()}
function interestPreview(amount,rate,months){const p=Number(amount),r=Number(rate),n=Number(months);if(!Number.isFinite(p)||!Number.isFinite(r)||p<0||p>100000000000||r<0||r>100)return 0;const product=BigInt(Math.round(p*100))*BigInt(Math.round(r*100))*BigInt(Math.max(1,Math.min(60,Math.trunc(n)||1)));return Number((product+5000n)/10000n)/100}
function loanForm(){const g=selected(),requestId=crypto.randomUUID();if(!g.data.members.length){toast('Add borrowers under People first.');return}modal('Record a member loan',`<label for="f-member">Borrower</label><select name="member" id="f-member">${g.data.members.map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select>${field('amount','Principal disbursed (MK)','number','','required min="0.01" max="100000000000" step="0.01"')}<div class="split">${field('rate','Agreed interest rate (%)','number','0','required min="0" max="100" step="0.01"')}${field('months','Term / number of monthly repayments','number','1','required min="1" max="60" step="1"')}</div>${choice('basis','How is interest agreed?',['Flat for whole term','Simple per month'])}${field('firstDue','First repayment due date','date','','required')}<div id="loanPreview" class="notice"></div>${financialFields('Loan agreement / group approval reference')}<p class="muted">Flat-term interest = principal × rate. Simple-monthly interest = principal × rate × months. The fixed agreed interest is spread over the term. Early settlement changes require an explicitly approved waiver.</p>`,async values=>{await api('loan',{...values,id:g.id,requestId});toast('Member loan recorded')});const update=()=>{const principal=Number($('#f-amount').value),interest=interestPreview($('#f-amount').value,$('#f-rate').value,$('#f-basis').value==='Simple per month'?$('#f-months').value:1);$('#loanPreview').textContent='Agreed total interest '+money(interest)+' · Total scheduled repayments '+money(principal+interest)};['#f-amount','#f-rate','#f-months'].forEach(s=>$(s).oninput=update);$('#f-basis').onchange=update;update()}
function repaymentForm(id,adjust=false){const g=selected(),l=g.data.loans.find(l=>l.id===id),st=loanState(g.data,l),requestId=crypto.randomUUID();modal(adjust?'Record approved loss or interest waiver':'Record loan repayment',`<h3>${esc(g.data.members.find(m=>m.id===l.member)?.name)}</h3><p>Principal outstanding ${money(st.principal)} · Agreed interest outstanding ${money(st.interest)}</p>${field('principal',adjust?'Principal written off (MK)':'Principal received (MK)','number','0',`required min="0" max="${st.principal}" step="0.01"`)}${field('interest',adjust?'Interest waived (MK)':'Interest received (MK)','number','0',`required min="0" max="${st.interest}" step="0.01"`)}<div id="repayPreview" class="notice"></div>${financialFields(adjust?'Required group-approved reason':'Repayment note / allocation agreement')}<p class="muted">${adjust?'This reduces the amounts expected and records a principal loss where applicable. It does not change cash.':'Record actual money received. Principal replenishes cash without being counted as a new contribution; only the interest portion is loan income.'}</p>`,async values=>{await api(adjust?'loan_adjustment':'repayment',{...values,id:g.id,entity:id,requestId});toast(adjust?'Approved adjustment recorded':'Repayment recorded')});const update=()=>$('#repayPreview').textContent=(adjust?'Total approved adjustment: ':'Actual cash repayment: ')+money(Number($('#f-principal').value)+Number($('#f-interest').value));$('#f-principal').oninput=update;$('#f-interest').oninput=update;update();if(adjust)$('#f-note').required=true}
function financeReport(d){const investments=d.investments||[],loans=d.loans||[];return `${investments.length?`<h2>Investment position</h2><div class="table"><table><thead><tr><th>Investment</th><th>Placed</th><th>Capital at cost</th><th>Cash returned</th><th>Realised gain/loss</th></tr></thead><tbody>${investments.map(iv=>{const st=investmentState(d,iv);return `<tr><td>${esc(iv.title)}</td><td>${money(iv.amount)}</td><td>${money(st.remaining)}</td><td>${money(st.cashReturned)}</td><td>${money(st.gain)}</td></tr>`}).join('')}</tbody></table></div>`:''}${loans.length?`<h2>Loan position (officer report)</h2><div class="table"><table><thead><tr><th>Borrower</th><th>Original principal</th><th>Outstanding principal</th><th>Agreed interest outstanding</th><th>Interest received</th><th>Overdue</th></tr></thead><tbody>${loans.map(l=>{const st=loanState(d,l);return `<tr><td>${esc(d.members.find(m=>m.id===l.member)?.name)}</td><td>${money(l.principal)}</td><td>${money(st.principal)}</td><td>${money(st.interest)}</td><td>${money(st.interestPaid)}</td><td>${money(st.overdue)}</td></tr>`}).join('')}</tbody></table></div>`:''}${d.plans?.length?`<h2>Plans and delivery</h2><div class="table"><table><thead><tr><th>Item</th><th>Planned cost</th><th>Actual spending</th><th>Status</th></tr></thead><tbody>${d.plans.map(pl=>`<tr><td>${esc(pl.title)}</td><td>${money(pl.budget)}</td><td>${money(planSpend(d,pl.id))}</td><td>${esc(pl.status)}</td></tr>`).join('')}</tbody></table></div>`:''}`}

async function init(){try{const r=await fetch('/.netlify/functions/config');if(!r.ok)throw Error('Setup unavailable');config=await r.json();const fragment=new URLSearchParams(location.hash.slice(1));const recovery=fragment.get('type')==='recovery';if(fragment.get('access_token')){setSession({access_token:fragment.get('access_token'),refresh_token:fragment.get('refresh_token'),expires_at:Math.floor(Date.now()/1000)+Number(fragment.get('expires_in')||3600)});history.replaceState(null,'',location.pathname+location.search);session.user=await auth('user',null,'GET',session.access_token);setSession(session)}if(config.ready&&(session||publicId))await sync();render();const returnedTx=new URLSearchParams(location.search).get('payment');if(returnedTx&&session){try{const out=await paymentAPI('verify',{tx_ref:returnedTx});toast(out.ok?'Your payment has been verified by PayChangu.':out.message);await sync();render()}catch(e){toast(e.message)}}if(recovery)modal('Choose a new password',field('password','New password','password','','required minlength="8" autocomplete="new-password"'),async d=>{await auth('user',{password:d.password},'PUT',await accessToken());toast('Password updated')},'Save password');setInterval(()=>{if(config.ready&&(session||publicId)&&!document.hidden)sync(true)},10000)}catch(e){$('#app').innerHTML=`<div class="card"><h1>We could not connect.</h1><p>${esc(e.message)}</p><button id="retry">Try again</button><a class="button" href="local.html">Open device ledger</a></div>`;$('#retry').onclick=()=>location.reload();account()}}
init();
